args.command:
$jobId = "1cbe0d2407ea"
$start = Get-Date
Write-Output "START $start job $jobId"
$maxTries = 40
for ($i=1; $i -le $maxTries; $i++) {
  try {
    $r = Invoke-RestMethod -Uri "http://localhost:8000/api/v1/jobs/$jobId" -Method Get
    $now = Get-Date
    $elapsed = [int]($now - $start).TotalSeconds
    Write-Output ("[{0}s try {1}] status={2} stage={3} progress={4} : {5}" -f $elapsed, $i, $r.status, $r.stage, $r.progress, ($r | ConvertTo-Json -Compress))
    if ($r.status -eq "ready" -or $r.status -eq "failed") {
      Write-Output ("FINISH $now ELAPSED {0}s" -f $elapsed)
      $r | ConvertTo-Json -Depth 10
      break
    }
  } catch {
    Write-Output ("try {0} error: {1}" -f $i, $_.Exception.Message)
  }
  Start-Sleep -Seconds 10
}
Write-Output "POLL DONE"

